import { ApolloClient, InMemoryCache, createHttpLink, ApolloLink, from } from '@apollo/client';
import { onError } from '@apollo/client/link/error';
import { setContext } from '@apollo/client/link/context';
import { refreshToken } from './services/auth';
import { RetryLink } from '@apollo/client/link/retry';

// HTTP connection to the API
const httpLink = createHttpLink({
  uri: 'http://localhost:8000/graphql',
  credentials: 'include', // This will include cookies with the request
});

// Middleware to add auth token to headers
const authLink = setContext((_, { headers = {} }) => {
  // Get the authentication token from local storage
  const token = localStorage.getItem('access_token');

  // Return the context with headers and credentials
  return {
    headers: {
      ...headers,
      authorization: token ? `Bearer ${token}` : '',
    },
    // Ensure credentials are included with every request
    credentials: 'include',
  };
});

// Error handling for authentication
const errorLink = onError(({ graphQLErrors, networkError, operation, forward }) => {
  if (graphQLErrors) {
    for (let err of graphQLErrors) {
      console.error('GraphQL Error:', err);

      // Handle token expiration or invalid token
      if (err.extensions?.code === 'UNAUTHENTICATED' || 
          err.message.includes('Not authenticated') ||
          err.message.includes('Invalid token') ||
          err.message.includes('Token expired')) {

        // Only attempt refresh if this isn't a refresh token request to avoid loops
        if (operation.operationName === 'RefreshToken') {
          console.log('Refresh token request failed, redirecting to login');
          clearAuthAndRedirect();
          return;
        }

        // Try to refresh the token
        const refreshTokenValue = localStorage.getItem('refresh_token');
        if (refreshTokenValue) {
          console.log('Attempting to refresh access token...');
          return refreshToken()
            .then(({ access_token, refresh_token }) => {
              if (!access_token) {
                throw new Error('No access token in refresh response');
              }

              console.log('Token refreshed successfully');

              // Update tokens in storage
              localStorage.setItem('access_token', access_token);
              if (refresh_token) {
                localStorage.setItem('refresh_token', refresh_token);
              }

              // Update the authorization header with the new token
              const oldHeaders = operation.getContext().headers;
              operation.setContext({
                headers: {
                  ...oldHeaders,
                  authorization: `Bearer ${access_token}`,
                },
              });

              // Retry the request with the new token
              return forward(operation);
            })
            .catch(error => {
              console.error('Failed to refresh token:', error);
              clearAuthAndRedirect();
              return;
            });
        } else {
          console.log('No refresh token available, redirecting to login');
          clearAuthAndRedirect();
          return;
        }
      }
    }
  }

  if (networkError) {
    console.error('[Network error]:', networkError);

    // Handle 401 Unauthorized
    if (networkError.statusCode === 401) {
      console.log('Received 401 Unauthorized, clearing auth and redirecting');
      clearAuthAndRedirect();
    }
  }
});

// Helper function to clear auth and redirect to login
function clearAuthAndRedirect() {
  localStorage.removeItem('access_token');
  localStorage.removeItem('refresh_token');
  // Clear all cookies by setting their expiration to the past
  document.cookie.split(';').forEach(c => {
    document.cookie = c.trim().split('=')[0] + '=;expires=Thu, 01 Jan 1970 00:00:00 UTC;path=/';
  });
  window.location.href = '/login';
}

// Custom retry link with exponential backoff and rate limit handling
const retryLink = new RetryLink({
  delay: {
    initial: 300,
    max: 10000, // 10 seconds max delay
    jitter: true
  },
  attempts: (count, operation, error) => {
    // Don't retry if we've already tried 5 times
    if (count > 5) return false;

    // Don't retry for certain operations that shouldn't be retried
    if (operation.operationName === 'Login' || 
        operation.operationName === 'RefreshToken') {
      return false;
    }

    // Check if this is a rate limit error
    const isRateLimitError = error?.result?.errors?.some(
      e => e.extensions?.code === 'RATE_LIMIT_EXCEEDED' || 
           error.statusCode === 429
    );

    // If it's a rate limit error, use a longer delay
    if (isRateLimitError) {
      // Exponential backoff: 1s, 2s, 4s, 8s, 10s
      const delay = Math.min(1000 * Math.pow(2, count - 1), 10000);
      return { delay };
    }

    // For other retryable errors, use default behavior
    const isNetworkError = !error.statusCode;
    const isServerError = error.statusCode >= 500;

    if (isNetworkError || isServerError) {
      return true;
    }

    return false;
  }
});

// Add response middleware to handle rate limit headers
const rateLimitLink = new ApolloLink((operation, forward) => {
  return forward(operation).map(response => {
    const context = operation.getContext();
    const { response: { headers } } = context;

    if (headers) {
      const rateLimitRemaining = headers.get('x-ratelimit-remaining');
      const rateLimitReset = headers.get('x-ratelimit-reset');

      if (rateLimitRemaining && parseInt(rateLimitRemaining, 10) < 10) {
        console.warn(`Approaching rate limit: ${rateLimitRemaining} requests remaining`);
      }
    }

    return response;
  });
});

// Create the Apollo Client instance with cache configuration
const client = new ApolloClient({
  link: from([
    retryLink,
    rateLimitLink,
    errorLink,
    authLink,
    httpLink,
  ]),
  cache: new InMemoryCache({
    typePolicies: {
      Query: {
        fields: {
          messages: {
            // Use field policy to handle pagination
            keyArgs: ['type'],
            merge(existing, incoming, { args: { offset = 0 } }) {
              const merged = existing ? existing.slice(0) : [];
              for (let i = 0; i < incoming.length; ++i) {
                merged[offset + i] = incoming[i];
              }
              return merged;
            },
          },
        },
      },
    },
  }),
  defaultOptions: {
    watchQuery: {
      fetchPolicy: 'cache-and-network',
      errorPolicy: 'all',
      notifyOnNetworkStatusChange: true,
    },
    query: {
      fetchPolicy: 'network-only',
      errorPolicy: 'all',
    },
    mutate: {
      errorPolicy: 'all',
    },
  },
});

// Export the client
export default client;
